import type {
    NotificationModuleCode,
    NotificationModulePolicy,
    NotificationSeverity,
    RealtimeNotificationPopupPayload,
    UpdateNotificationModulePolicyInput,
    UpdateUserNotificationPreferenceInput,
    UserNotificationModulePreference,
} from '@/shared/types/notification/notification.types';

export interface LocalizedModuleCopy {
    name: string;
    description: string;
}

export function pickLocalizedModuleCopy(
    item: Pick<
        NotificationModulePolicy,
        | 'displayNameVi'
        | 'displayNameEn'
        | 'displayNameJa'
        | 'descriptionVi'
        | 'descriptionEn'
        | 'descriptionJa'
    >,
    locale: string,
): LocalizedModuleCopy {
    if (locale === 'en') {
        return {name: item.displayNameEn, description: item.descriptionEn};
    }
    if (locale === 'ja') {
        return {name: item.displayNameJa, description: item.descriptionJa};
    }
    return {name: item.displayNameVi, description: item.descriptionVi};
}

export function toUpdateModulePolicyPayload(
    current: NotificationModulePolicy,
    patch: Partial<UpdateNotificationModulePolicyInput>,
): UpdateNotificationModulePolicyInput {
    const mandatory = patch.mandatory ?? current.mandatory;
    const rawCooldown = patch.cooldownSeconds ?? current.cooldownSeconds;
    const cooldownSeconds = Number.isFinite(rawCooldown)
        ? Math.min(86400, Math.max(0, Math.round(rawCooldown)))
        : 0;
    return {
        enabled: patch.enabled ?? current.enabled,
        severity: patch.severity ?? current.severity,
        mandatory,
        inAppEnabled: mandatory ? true : (patch.inAppEnabled ?? current.inAppEnabled),
        screenPopupEnabled: mandatory
            ? true
            : (patch.screenPopupEnabled ?? current.screenPopupEnabled),
        desktopOsEnabled: patch.desktopOsEnabled ?? current.desktopOsEnabled,
        mobilePushEnabled: patch.mobilePushEnabled ?? current.mobilePushEnabled,
        emailEnabled: patch.emailEnabled ?? current.emailEnabled,
        cooldownSeconds,
    };
}

export function toUpdateUserPreferencePayload(
    current: UserNotificationModulePreference,
    patch: Partial<UpdateUserNotificationPreferenceInput>,
): UpdateUserNotificationPreferenceInput {
    if (current.mandatory) {
        return {
            muted: false,
            screenPopupEnabled: true,
            desktopOsEnabled: patch.desktopOsEnabled ?? current.desktopOsEnabled,
            mobilePushEnabled: patch.mobilePushEnabled ?? current.mobilePushEnabled,
            emailEnabled: patch.emailEnabled ?? current.emailEnabled,
        };
    }
    return {
        muted: patch.muted ?? current.muted,
        screenPopupEnabled: patch.screenPopupEnabled ?? current.screenPopupEnabled,
        desktopOsEnabled: patch.desktopOsEnabled ?? current.desktopOsEnabled,
        mobilePushEnabled: patch.mobilePushEnabled ?? current.mobilePushEnabled,
        emailEnabled: patch.emailEnabled ?? current.emailEnabled,
    };
}

export function popupDurationMs(severity?: NotificationSeverity | null): number {
    if (severity === 'CRITICAL') return 0;
    if (severity === 'ACTION') return 6500;
    return 4500;
}

export function resolveNotificationPortalHref(
    area: 'customer' | 'operations' | 'admin',
    item: Pick<
        RealtimeNotificationPopupPayload,
        'moduleCode' | 'referenceType' | 'referenceId'
    >,
): string {
    const ref = (item.referenceType || item.moduleCode || '').toUpperCase();
    const id = item.referenceId;

    if (area === 'customer') {
        if (ref === 'MISSION' && id) return `/customer/missions/${id}`;
        if (ref === 'INVOICE' || ref === 'BILLING' || ref === 'QUOTA' || ref === 'PAYMENT') {
            return '/customer/billing';
        }
        if (ref === 'MARKETPLACE' || ref === 'ESCROW' || ref === 'PAYOUT' || ref === 'LISTING') {
            return '/customer/provider/orders';
        }
        if (ref === 'AIRSPACE' || ref === 'PERMIT') {
            return id ? `/customer/missions/${id}` : '/customer/missions';
        }
        return '/customer/notifications';
    }

    if (area === 'operations') {
        if (ref === 'SAR') return '/operations/sar-cockpit';
        if ((ref === 'MISSION' || ref === 'PERMIT' || ref === 'AIRSPACE') && id) {
            return `/operations/missions/${id}`;
        }
        if (ref === 'MAINTENANCE' || ref === 'REPAIR') return '/operations/maintenance';
        return '/operations/notifications';
    }

    if (ref === 'SUPPORT') return '/admin/support';
    if (ref === 'INVOICE' || ref === 'BILLING' || ref === 'QUOTA' || ref === 'PAYMENT') {
        return '/admin/billing';
    }
    if (ref === 'MARKETPLACE' || ref === 'ESCROW' || ref === 'PAYOUT') {
        return '/admin/billing/payouts';
    }
    if (ref === 'LISTING') return '/admin/marketplace/listings';
    if (ref === 'PROVIDER') return '/admin/marketplace/providers';
    if (ref === 'AIRSPACE' || ref === 'PERMIT') return '/admin/airspace';
    if (ref === 'STORAGE' || ref === 'DRIVE' || ref === 'FILE') return '/admin/infrastructure/storage';
    if (ref === 'USER' && id) return `/admin/users/${id}`;
    return '/admin/notifications';
}

export function formatModuleBadgeLabel(code?: NotificationModuleCode | null): string {
    return code || 'SYSTEM';
}
